import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { FeedbackService } from 'src/app/services/feedback.service';
import { Feedback } from 'src/app/models/feedback.model';

@Component({
  selector: 'app-user-feedback',
  templateUrl: './user-feedback.component.html',
  styleUrls: ['./user-feedback.component.css'],
})
export class UserFeedbackComponent implements OnInit {
  successMessage: string = '';
  itemId: number = 0;

  feedback: Feedback = {
    customerName: '',
    email: '',
    message: '',
  };

  constructor(
    private route: ActivatedRoute,
    private feedbackService: FeedbackService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.route.queryParams.subscribe((params) => {
      this.successMessage = params['success'] || '';
      this.itemId = +params['itemId'] || 0;

      // Optionally pre-fill customer name/email from localStorage
      const storedName = localStorage.getItem('username');
      if (storedName) {
        this.feedback.customerName = storedName;
        this.feedback.email = storedName + '@example.com'; // Replace if email is stored
      }
    });
  }

  onSubmit() {
    this.feedbackService.submitFeedback(this.feedback).subscribe((res) => {
      alert('Thank you for your feedback!');
      this.router.navigate(['/user/items']);
    });
  }

  skipFeedback() {
    this.router.navigate(['/user/items']);
  }
}
<h2>Submit Feedback</h2>
<form (ngSubmit)="onSubmit()" #form="ngForm">
  <label>Name:</label>
  <input
    type="text"
    [(ngModel)]="feedback.customerName"
    customerName="name"
    required
  /><br />

  <label>Email:</label>
  <input
    type="email"
    [(ngModel)]="feedback.email"
    customerName="email"
    required
  /><br />

  <label>Message:</label>
  <textarea
    [(ngModel)]="feedback.message"
    customerName="message"
    required
  ></textarea
  ><br />

  <button type="submit" [disabled]="form.invalid">Submit</button>
</form>
